# Phase 4: Naturalist (2.0.7). Sources: Naturalist 2.x changelogs, the minecraft-guides.com Naturalist wiki (2026-10),
# checked against the jar where they disagree (Mole and Lizard have no breeding goal, Fireflies vanish in sunlight
# instead of burning, Hippos attack boats, Dragonflies breathe a harming cloud when fed Chorus Fruit).
# Shared texts (breeds_alone, lifespan.*) come from pages_vanilla_passive.py.
N = "naturalist"
OCEANS = "all oceans except frozen ones"
PAGES = {
    (N, "alligator"): (["Lives in Swamps, Mangrove Swamps and along Rivers, and breathes underwater. It attacks players in the water, at night and near its eggs, and hunts Deer, Ducks, Snakes, Catfish and Frogs. It lays Alligator Eggs."], ["food", "breeds_alone", "lifespan.long"]),
    (N, "anglerfish"): ([f"Lives deep in {OCEANS}, in the dark; the deepest ones glow. It hunts Cod and Tropical Fish and bites back when hit. Comes in random sizes, and can be caught in a Bucket."], []),
    (N, "ant"): (["Lives in Ant Hills in Jungles and Savannas. Ants carry food they find on the ground back to their hill, get angry if you take it, and the whole colony attacks whoever hurts one of them. Sugar heals them. Plant a Queen Ant to start your own hill, whose Ants defend you."], []),
    (N, "bass"): (["Lives in Rivers, Swamps and Mangrove Swamps, in schools of the same size. Bigger Bass are rarer, eat smaller ones and sometimes grow even bigger. Comes in random sizes, and can be caught in a Bucket."], []),
    (N, "bear"): ([
        "Lives in forests, taigas and Groves. It sleeps at midday and after midnight, and attacks players at night, in the dark and near its cubs. It raids Beehives, Sweet Berry Bushes and Campfires and picks up food from the ground: dropping some can calm a chasing Bear.",
        "A cub fed its food can be tamed. Shear an adult for Fur, best while it sleeps.",
    ], ["food", "breeds_alone", "lifespan.long"]),
    (N, "bird"): (["Lives in almost every land biome, and its species depends on where it lives. It flees from you unless you crouch. Throw its food on the ground to tame it: a tamed Bird sits on your head and slows your falls, and with a Parrot on each shoulder too you can fly slowly. Crouch to let it down."], ["food"]),
    (N, "black_bear"): ([
        "Lives in forests, taigas and Groves. It sleeps at midday and after midnight, and attacks players at night, in the dark and near its cubs. It raids Beehives, Sweet Berry Bushes and Campfires and picks up food from the ground: dropping some can calm a chasing Bear.",
        "A cub fed its food can be tamed. Shear an adult for Fur, best while it sleeps.",
    ], ["food", "breeds_alone", "lifespan.long"]),
    (N, "blobfish"): ([f"Lives deep in {OCEANS}, near the sea floor. Brought close to the surface it turns into a shapeless blob, and gets its shape back in the deep. It hunts Crabs and Snails. Comes in random sizes, and can be caught in a Bucket."], []),
    (N, "boar"): (["Lives in forests and Savannas, in small groups. It fights back when hit."], ["food", "breeds_alone", "lifespan.medium"]),
    (N, "butterfly"): (["Lives in forests, Plains and Swamps. It collects nectar from flowers and helps nearby crops grow. Butterflies that fall in love lay a Caterpillar instead of having a baby."], ["food", "breeds_alone", "lifespan.very_short"]),
    (N, "capybara"): (["Lives in Jungles, Swamps and Mangrove Swamps. Completely peaceful, it sleeps through the day, swims well and takes no fall damage. Its food can tame it."], ["food", "breeds_alone", "lifespan.medium"]),
    (N, "caterpillar"): (["Born from Butterflies. It climbs the side of a log and turns into a Chrysalis, which hatches into a Butterfly."], []),
    (N, "catfish"): (["Lives in Swamps and Mangrove Swamps. It hunts small fish and Tadpoles and swallows Bass whole. Comes in random sizes, and can be caught in a Bucket."], []),
    (N, "clam"): ([f"Lives on the floor of {OCEANS}. Some hold a treasure and snap shut when you come close, unless you crouch: take it while the Clam is open. It's almost unhurtable while closed, and opening under your feet it throws you up."], []),
    (N, "crab"): (["Lives on Beaches and Stony Shores. It hides in its shell when you come close, unless you crouch or hold its food, which can tame it. It picks up swords and tools from the ground and fights with them. Tamed Crabs dance to Jukeboxes."], ["food", "breeds_alone", "lifespan.short"]),
    (N, "deer"): (["Lives in forests, Groves and Cherry Groves. It grazes, runs from players unless they crouch, and from Bears, Tigers, Alligators and Wolves. Its Antlers brew into a potion."], ["food", "breeds_alone", "lifespan.medium"]),
    (N, "desert_scorpion"): (["Lives in Deserts and Badlands. Its sting poisons, and it attacks players in the dark, like Spiders. It hunts Lizards, and Lizard Tails heal it. Caught with a Capture Net and released, it stops attacking players."], []),
    (N, "dragonfly"): (["Lives in Swamps and Mangrove Swamps. A Frog that eats one drops Froglass of its color. Feed it Chorus Fruit and it breathes a small harmful cloud."], []),
    (N, "duck"): (["Lives in Rivers, Swamps and Mangrove Swamps, and swims as much as it walks. Its food can tame a duckling, and it lays Duck Eggs. A duckling can be scooped up with a Bucket."], ["food", "breeds_alone", "lifespan.short"]),
    (N, "elephant"): (["Lives in Savannas. It gets angry when hit or when its calves are, and its food heals it. Feed a calf Cake a few times to tame it: once grown it can be saddled, ridden and given a Chest."], ["food", "breeds_alone", "lifespan.very_long"]),
    (N, "firefly"): (["Comes out at night in forests, Plains, Swamps, Mushroom Fields and the Glimmering Weald. It flashes in the dark, vanishes in sunlight and drops Glow Goop."], []),
    (N, "giant_isopod"): ([f"Lives on the floor of {OCEANS}. It curls up when you come close, taking less damage. It can be caught in a Bucket."], ["food", "breeds_alone", "lifespan.short"]),
    (N, "giraffe"): (["Lives in Savannas and never attacks. Its food can tame a calf: once grown, ride it with an empty hand, no Saddle needed."], ["food", "breeds_alone", "lifespan.long"]),
    (N, "great_white_shark"): (["Lives in Warm and Lukewarm oceans. It hunts fish, and attacks players swimming in the dark, charging and circling back between strikes. Its food heals it, but it can't be tamed."], ["food"]),
    (N, "hedgehog"): (["Lives in forests, Plains, Meadows and taigas. It rolls into a ball when you come close, unless you crouch or hold its food, hurting whatever touches it. It ignores fall damage, Cactus and Sweet Berry Bushes. Its food can tame it."], ["food", "breeds_alone", "lifespan.short"]),
    (N, "hippo"): (["Lives in Savannas and Jungles. It attacks players in the water, follows them onto land and attacks boats. A calf is tamed with its food, and a tamed Hippo leaves you alone in the water."], ["food", "breeds_alone", "lifespan.long"]),
    (N, "jellyfish"): ([f"Drifts in {OCEANS}, stinging whatever touches it. Comes in random sizes, and can be caught in a Bucket."], []),
    (N, "jungle_scorpion"): (["Lives in Jungles. Bigger than the Desert Scorpion, its sting poisons, and it attacks players in the dark, like Spiders. It hunts Lizards, and Lizard Tails heal it."], []),
    (N, "komodo_dragon"): (["Lives in Deserts, Badlands, Savannas and Jungles. It basks in the sun, hunts small animals, and turns on players who stay near it for a while. Its bite poisons. It can't be tamed."], ["food", "breeds_alone", "lifespan.long"]),
    (N, "lion"): (["Lives in Savannas, in prides led by a maneless Lion. It sleeps by day, hunts Zebras, Rhinos, Boars and Horses at night, and defends its cubs. A cub fed its food can be tamed."], ["food", "breeds_alone", "lifespan.long"]),
    (N, "lizard"): (["Lives in Deserts, Savannas, Jungles, Swamps and forests. When badly hurt it drops its tail to escape, and grows it back later. Its food tames it, and tamed Lizards get tougher. It can't be bred."], ["food"]),
    (N, "mammoth"): (["Lives in Snowy Plains, Ice Spikes, Snowy Slopes and Frozen Peaks, in herds. Its hits throw you into the air, and it avoids Bees. Feed a calf Cake a few times to tame it: once grown it can be saddled, ridden and given a Chest."], ["food", "breeds_alone", "lifespan.very_long"]),
    (N, "mole"): (["Lives in forests, Plains and Meadows. It burrows when it spots undead, sprinting players or whoever hurt it, and can't be hurt underground except when it peeks out. Fire, water and Wolves force it out. It can't be tamed or bred."], []),
    (N, "ostrich"): (["Lives in Savannas. It buries its head when you come close, unless you crouch or hold its food, which tames a chick at once. Once grown it can be saddled, ridden and made to jump, and falls slowly. It lays eggs on Sand or Dirt and attacks anyone who comes near them; Zombies trample them."], ["food", "breeds_alone", "lifespan.medium"]),
    (N, "piranha"): (["Lives in Jungle waters and Lush Caves, in big schools that follow their leader and attack players in the water. Hit one and the whole school comes for you. Comes in random sizes, and can be caught in a Bucket."], []),
    (N, "rat"): (["Lives in forests, Plains and Groves, and climbs walls. Its food tames it easily. Release a tamed Rat from a Capture Net onto a Chest and it harvests and replants the ripe crops around it, storing them inside."], ["food", "breeds_alone", "lifespan.short"]),
    (N, "ray"): ([f"Glides near the floor of {OCEANS}. Hit it and its sting poisons you. Comes in random sizes, and can be caught in a Bucket."], []),
    (N, "rhino"): (["Lives in Savannas, in small groups. Adults charge at players near their young. It can't be tamed or bred."], []),
    (N, "snail"): (["Lives in most temperate biomes and in caves. It climbs walls, hides in its shell when you come close, taking less damage, and now and then makes Slime Balls. It lays Snail Eggs and can be dyed."], ["food", "breeds_alone", "lifespan.short"]),
    (N, "snake"): (["Lives in forests, plains, Jungles, Swamps, Rivers, Beaches and dry biomes: Coral Snakes and Rattlesnakes in warm ones, green Snakes elsewhere. It hunts small animals; Coral Snakes and Rattlesnakes poison, and Rattlesnakes rattle when you come close. Some of its food tames it."], ["food"]),
    (N, "starfish"): ([f"Lives on the floor of {OCEANS}. It drops itself as a block you can place, and can be caught in a Bucket."], []),
    (N, "tiger"): (["Lives alone in Jungles, Dark Forests, Cherry Groves, mountains, snowy slopes, Badlands, Deserts and Swamps, as a Tiger, White Tiger, Leopard or Black Panther depending on the biome. It sleeps by day, stalks Boars, Pigs, Deer, Zebras and Snakes at night and fights back when hit. A cub fed its food can be tamed."], ["food", "breeds_alone", "lifespan.long"]),
    (N, "tortoise"): (["Lives in Deserts, Jungles and Swamps. It hides in its shell when you come close, unless you crouch or hold its food, taking less damage and barely knocked back. Its food can tame it, and it lays Tortoise Eggs. Tamed Tortoises get tougher."], ["food", "breeds_alone", "lifespan.long"]),
    (N, "turkey"): (["Lives in forests, taigas and Groves. It runs from players unless they crouch or hold its food, and chases Ants. It falls slowly and takes no fall damage."], ["food", "breeds_alone", "lifespan.short"]),
    (N, "vulture"): (["Flies high over Deserts, Badlands and Savannas and perches on Cacti. It picks up Rotten Flesh, attacks Zombies, and dives at players low on health who hold something, unless it's already carrying Rotten Flesh."], []),
    (N, "whale"): ([f"Lives in {OCEANS}, surfacing for air before diving back down. Jellyfish and Pufferfish can't sting it."], ["food", "breeds_alone"]),
    (N, "zebra"): (["Lives in Savannas, in herds, and runs from players. Tame it by riding it until it stops throwing you off; then it can be saddled and given a Chest."], ["food", "breeds_alone", "lifespan.very_long"]),
}
